from collections import deque
def solution(root):
    if not root:
        return []
    res = []
    q = deque([root])
    while q:
        level_sz = len(q)
        curr_level = []
        for _ in range(level_sz):
            node = q.popleft()
            curr_level.append(node.val)
            if node.left: q.append(node.left)
            if node.right: q.append(node.right)
        res.append(curr_level)
    return res
